-- ----- fragment: minion_isaiah_46.sql (Isaiah 46) -----
-- Chapter: Isaiah 46 — BEL AND NEBO STOOP / YAHUAH CARRIES HIS PEOPLE. Babylon's gods are loaded
-- on weary beasts and hauled into captivity — a dead weight that cannot deliver even itself (46:1-2);
-- against that, Yahuah is the One who *carries* his people from the belly to the hoar hairs, *I have
-- made, and I will bear; even I will carry, and will deliver* (46:3-4). The idol must be borne; Yahuah
-- bears. And only He foretells: *I am Elohim (God), and there is none else... Declaring the end from
-- the beginning... My counsel shall stand* (46:9-10) — the named *ravenous bird from the east*, Cyrus,
-- is His counsel walking the earth (46:11). The Formed and the Formless: Yahuah ALONE speaks the end
-- from the beginning and accomplishes it; no co-equal, no rival, no carried god.
-- Tag: isa46   Temp view: _s303_isa46_lookup
-- Sort band: base 27125, step 3 -> threads at 27125, 27128, 27131 (3 threads)
-- Source of EVERY row: 'canon','isaiah',46,v
--
-- Isaiah 46 coverage:
--   v.1-2 (Bel boweth down, Nebo stoopeth, their idols were upon the beasts... they could not deliver
--          the burden, but themselves are gone into captivity)
--        NT:     none warranted (the idol-vanity weave runs LATERALLY in the Tanakh here; the NT idol
--                weave is carried under THREAD 3's I-am-El framing)
--        Extras: none warranted (clean lateral Tanakh witnesses carry it)
--        Tanakh: ★ Jeremiah 10:5 (they must needs be borne, because they cannot go), ★ Psalm 115:4-7
--                (idols that cannot move/speak/see), ★ 1 Samuel 5:3-4 (Dagon fallen on his face before
--                the ark) — THREAD 1
--   ★ v.3-4 (Hearken unto me, O house of Jacob... which are borne by me from the belly... and even to
--          hoar hairs will I carry you: I have made, and I will bear; even I will carry, and will deliver)
--        NT:     ★ Matthew 11:28 (Come unto me, all ye that labour and are heavy laden, and I will give
--                you rest) — THREAD 2 (lateral-forward; the burden-bearer named in the flesh)
--        Extras: none warranted (the carrying-from-the-womb weave is Tanakh-and-NT)
--        Tanakh: ★ Psalm 71:6 (By thee have I been holden up from the womb), Psalm 71:18 (now also when
--                I am old and grayheaded... forsake me not), ★ Deuteronomy 1:31 (Yahuah thy Elohim bare
--                thee, as a man doth bear his son), ★ Isaiah 63:9 (he bare them, and carried them all
--                the days of old) — THREAD 2
--   v.5-8 (To whom will ye liken me... they lavish gold... he maketh it a god... yet can he not answer)
--        NT:     none warranted (the made-god-that-cannot-save is the idol-vanity of THREAD 1's frame,
--                woven into THREAD 1/THREAD 3 prose, not forced to a separate add)
--        Extras: none warranted
--        Tanakh: held in prose — the carried-god-that-cannot-answer is the contrast THREAD 2 turns on
--   ★ v.9-10 (I am Elohim (God), and there is none else... Declaring the end from the beginning... My
--          counsel shall stand, and I will do all my pleasure)
--        NT:     ★★ Revelation 22:13 (I am Alpha and Omega, the beginning and the end, the first and
--                the last), ★ Acts 15:18 (Known unto Elohim (God) are all his works from the beginning
--                of the world) — THREAD 3
--        Extras: none warranted
--        Tanakh: ★ Isaiah 41:4 (calling the generations from the beginning... I am he), ★ Isaiah 48:3
--                (I have declared the former things from the beginning... I shewed them) — THREAD 3
--   v.11 (Calling a ravenous bird from the east, the man that executeth my counsel from a far country)
--        NT:     none warranted (Cyrus is the named Tanakh instrument; the weave is lateral)
--        Extras: none warranted
--        Tanakh: ★ Isaiah 44:28 (That saith of Cyrus, He is my shepherd), ★ Isaiah 45:1 (Thus saith
--                Yahuah (LORD) to his anointed, to Cyrus) — folded into THREAD 3 (the counsel that
--                stands made visible in the named man), NOT a forced separate thread
--   v.12-13 (Hearken unto me, ye stouthearted... I bring near my righteousness... and I will place
--          salvation in Zion for Yashar'el (Israel) my glory)
--        NT:     none warranted distinct
--        Extras: none warranted
--        Tanakh: held in prose (the salvation placed in Zion is the close of the I-am-El oracle of
--                THREAD 3; recorded, woven, not silently skipped)
--
-- Threads (slug — target libraries):
--   1. isaiah-46-bel-boweth-down-the-idols-a-dead-weight — Tanakh (Jeremiah 10, Psalm 115, 1 Samuel 5) [free]
--      (the carried gods that cannot move nor deliver themselves; Dagon fallen before the ark)
--   2. isaiah-46-even-to-hoar-hairs-will-i-carry-you — Tanakh (Psalm 71, Deuteronomy 1, Isaiah 63) + NT (Matthew 11) [free]
--      (★ the contrast: the idol must be carried, but Yahuah CARRIES his people from womb to old age)
--   3. isaiah-46-i-am-el-declaring-the-end-from-the-beginning — Tanakh (Isaiah 41, 48, 44, 45) + NT (Revelation 22, Acts 15) [free]
--      (★ Yahuah ALONE foretells and accomplishes; the named Cyrus = His counsel that stands)
--
-- Framing notes:
--   THE IDOLS A DEAD WEIGHT (THREAD 1): *Bel boweth down, Nebo stoopeth, their idols were upon the
--      beasts, and upon the cattle: your carriages were heavy loaden; they are a burden to the weary
--      beast... they could not deliver the burden, but themselves are gone into captivity* (Isaiah
--      46:1-2). Babylon's gods are cargo. Jeremiah names the same impotence: *They are upright as the
--      palm tree, but speak not: they must needs be borne, because they cannot go* (Jeremiah 10:5); the
--      Psalm catalogues it limb by limb: *They have mouths, but they speak not... feet have they, but
--      they walk not* (Psalm 115:5-7); and the ark of Yahuah leaves the carried god *fallen upon his
--      face to the earth* (1 Samuel 5:3-4) — Dagon a broken stump before the living Presence. The
--      carried god cannot deliver itself, much less the man who hauls it.
--   ★ EVEN TO HOAR HAIRS WILL I CARRY YOU (THREAD 2): the hinge of the chapter. The idol must be borne;
--      Yahuah BEARS. *Hearken unto me, O house of Jacob... which are borne by me from the belly, which
--      are carried from the womb: And even to your old age I am he; and even to hoar hairs will I carry
--      you: I have made, and I will bear; even I will carry, and will deliver you* (Isaiah 46:3-4). The
--      Psalmist sings it from both ends of a life: *By thee have I been holden up from the womb* (Psalm
--      71:6) and *Now also when I am old and grayheaded, O Elohim (God), forsake me not* (Psalm 71:18).
--      Moses preaches the wilderness as one long carrying: *Yahuah Elohayka (the LORD thy God) bare
--      thee, as a man doth bear his son* (Deuteronomy 1:31). Isaiah will say it again of the exodus:
--      *he bare them, and carried them all the days of old* (Isaiah 63:9). And the burden-bearer speaks
--      it in the flesh: *Come unto me, all ye that labour and are heavy laden, and I will give you rest*
--      (Matthew 11:28) — the Formed Son, the same arm that carried Jacob from the womb, lifting the
--      weary load no idol could ever bear. The covenant people are CARRIED, not carriers; this is the
--      house of Jacob and the remnant of Yashar'el, both houses borne home.
--   ★ I AM EL, DECLARING THE END FROM THE BEGINNING (THREAD 3): the Formed-and-Formless proof against
--      every dumb idol. *Remember the former things of old: for I am Elohim (God), and there is none
--      else; I am Elohim (God), and there is none like me, Declaring the end from the beginning, and
--      from ancient times the things that are not yet done, saying, My counsel shall stand, and I will
--      do all my pleasure* (Isaiah 46:9-10). Only Yahuah foretells: *calling the generations from the
--      beginning... I am he* (Isaiah 41:4); *I have declared the former things from the beginning... I
--      did them suddenly, and they came to pass* (Isaiah 48:3). The NT seals the same Name on the same
--      throne: *I am Alpha and Omega, the beginning and the end, the first and the last* (Revelation
--      22:13); *Known unto Elohim (God) are all his works from the beginning of the world* (Acts 15:18).
--      And the proof His counsel STANDS is the named man: *Calling a ravenous bird from the east, the
--      man that executeth my counsel from a far country* (Isaiah 46:11) — Cyrus, foretold by name a
--      lifetime before: *That saith of Cyrus, He is my shepherd, and shall perform all my pleasure*
--      (Isaiah 44:28); *Thus saith Yahuah (LORD) to his anointed, to Cyrus* (Isaiah 45:1). The One who
--      speaks the end from the beginning is the One who carries his people to it — no co-equal rival,
--      no carried god, Yahuah alone.
--   VERSES WITH NO SEPARATE ADD: v.5-8 (the made-god-that-cannot-answer — the idol-vanity woven into
--      THREAD 1's contrast and THREAD 3's I-am-El frame), v.11 Cyrus (folded into THREAD 3, the counsel
--      made visible in the named man — not forced to its own thread), v.12-13 (the righteousness brought
--      near, salvation placed in Zion — the close of THREAD 3's oracle). All recorded, none skipped.

CREATE TEMP VIEW _s303_isa46_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id=c.id JOIN books b ON c.book_id=b.id
  JOIN editions e ON b.edition_id=e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29');

INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM (VALUES
    -- THREAD 1: Bel boweth down — the idols a dead weight (the carried gods that cannot deliver)
    ('canon','isaiah',46,1,'canon','jeremiah',10,5,'free',
      E'*They are upright as the palm tree, but speak not: they must needs be borne, because they cannot go. Be not afraid of them; for they cannot do evil, neither also is it in them to do good* (Jeremiah 10:5). The gods of Babylon *upon the beasts, and upon the cattle* (Isaiah 46:1) are exactly Jeremiah''s carried idol — *they must needs be borne, because they cannot go*. A god that must be hauled cannot walk to help you; the weary beast bears a thing that *cannot do evil, neither... good*.'),
    ('canon','isaiah',46,2,'canon','psalms',115,5,'free',
      E'*They have mouths, but they speak not: eyes have they, but they see not* (Psalm 115:5). When *they could not deliver the burden, but themselves are gone into captivity* (Isaiah 46:2), it is the Psalm''s dead idol marching off in chains — *mouths, but they speak not; eyes... but they see not*. The carried god has every organ and no life; it goes where the conqueror drags it.'),
    ('canon','isaiah',46,2,'canon','psalms',115,7,'free',
      E'*They have hands, but they handle not: feet have they, but they walk not: neither speak they through their throat* (Psalm 115:7). Bel and Nebo *could not deliver the burden, but themselves are gone into captivity* (Isaiah 46:2) — feet that cannot walk, hands that cannot save, *so is every one that trusteth in them* (Psalm 115:8). The idol cannot deliver itself, let alone its maker.'),
    ('canon','isaiah',46,1,'canon','1-samuel',5,4,'free',
      E'*And when they arose early on the morrow morning, behold, Dagon was fallen upon his face to the ground before the ark of Yahuah (LORD); and the head of Dagon and both the palms of his hands were cut off upon the threshold; only the stump of Dagon was left to him* (1 Samuel 5:4). *Bel boweth down, Nebo stoopeth* (Isaiah 46:1) is Dagon''s fall written large: the carried god *fallen upon his face* before the living Presence, reduced to a *stump*. Set the idol beside Yahuah and it cannot keep its feet.')

    ,
    -- THREAD 2 (★): Even to hoar hairs will I carry you — Yahuah carries his people from womb to old age
    ('canon','isaiah',46,3,'canon','psalms',71,6,'free',
      E'*By thee have I been holden up from the womb: thou art he that took me out of my mother''s bowels: my praise shall be continually of thee* (Psalm 71:6). *Which are borne by me from the belly, which are carried from the womb* (Isaiah 46:3) is the Psalmist''s own confession — *holden up from the womb*. The covenant people, like the praying man, were carried before they could walk; the bearing began at the belly.'),
    ('canon','isaiah',46,4,'canon','psalms',71,18,'free',
      E'*Now also when I am old and grayheaded, O Elohim (God), forsake me not; until I have shewed thy strength unto this generation* (Psalm 71:18). *Even to your old age I am he; and even to hoar hairs will I carry you* (Isaiah 46:4) answers the gray-headed prayer directly: the One who held him from the womb does not set him down at the *hoar hairs*. From belly to grayhead, the same arm bears.'),
    ('canon','isaiah',46,4,'canon','deuteronomy',1,31,'free',
      E'*And in the wilderness, where thou hast seen how that Yahuah Elohayka (the LORD thy God) bare thee, as a man doth bear his son, in all the way that ye went, until ye came into this place* (Deuteronomy 1:31). *I have made, and I will bear; even I will carry, and will deliver you* (Isaiah 46:4) is the wilderness carrying made a lifelong promise — *Yahuah... bare thee, as a man doth bear his son*. The exodus was one long bearing of a child who could not walk himself home.'),
    ('canon','isaiah',46,4,'canon','isaiah',63,9,'free',
      E'*In all their affliction he was afflicted, and the angel of his presence saved them: in his love and in his pity he redeemed them; and he bare them, and carried them all the days of old* (Isaiah 63:9). *Even I will carry, and will deliver you* (Isaiah 46:4) is the very thing Isaiah remembers of the exodus — *he bare them, and carried them all the days of old*. The Formed One, the *angel of his presence*, is the arm that bore Yashar''el; idols are carried, but He carries.'),
    ('canon','isaiah',46,4,'canon','matthew',11,28,'free',
      E'*Come unto me, all ye that labour and are heavy laden, and I will give you rest* (Matthew 11:28). The weary beast staggers under *carriages... heavy loaden* (Isaiah 46:1), but the people of the carrying-Elohim are told *I will bear; even I will carry, and will deliver you* (Isaiah 46:4) — and the Formed Son says it in the flesh: *all ye that labour and are heavy laden... I will give you rest*. The same arm that carried Jacob from the womb lifts the heavy load no idol could ever bear.')

    ,
    -- THREAD 3 (★): I am El, declaring the end from the beginning — Yahuah alone foretells and accomplishes
    ('canon','isaiah',46,9,'canon','isaiah',41,4,'free',
      E'*Who hath wrought and done it, calling the generations from the beginning? I Yahuah (LORD), the first, and with the last; I am he* (Isaiah 41:4). *I am Elohim (God), and there is none else... I am he* (Isaiah 46:9) is the same self-disclosure — *the first, and with the last; I am he*. The God who calls the generations from the beginning is the only One who can declare what they hold.'),
    ('canon','isaiah',46,10,'canon','isaiah',48,3,'free',
      E'*I have declared the former things from the beginning; and they went forth out of my mouth, and I shewed them; I did them suddenly, and they came to pass* (Isaiah 48:3). *Declaring the end from the beginning... My counsel shall stand* (Isaiah 46:10) is proved by track record — *I shewed them... and they came to pass*. The word spoken and the word fulfilled are the same word; no idol has ever foretold and then performed.'),
    ('canon','isaiah',46,10,'canon','revelation',22,13,'free',
      E'*I am Alpha and Omega, the beginning and the end, the first and the last* (Revelation 22:13). *Declaring the end from the beginning, and from ancient times the things that are not yet done* (Isaiah 46:10) is the Name that closes the whole library: *the beginning and the end, the first and the last*. The One who holds both ends of time is the One whose counsel must stand; the throne speaks Isaiah''s own self-title.'),
    ('canon','isaiah',46,10,'canon','acts',15,18,'free',
      E'*Known unto Elohim (God) are all his works from the beginning of the world* (Acts 15:18). *My counsel shall stand, and I will do all my pleasure* (Isaiah 46:10) is exactly what James confesses at the council — *Known unto Elohim (God) are all his works from the beginning of the world*. The ingathering of the nations is no afterthought; it was His counsel from of old, standing as He said.'),
    ('canon','isaiah',46,11,'canon','isaiah',44,28,'free',
      E'*That saith of Cyrus, He is my shepherd, and shall perform all my pleasure: even saying to Jerusalem, Thou shalt be built; and to the temple, Thy foundation shall be laid* (Isaiah 44:28). *Calling a ravenous bird from the east, the man that executeth my counsel from a far country* (Isaiah 46:11) is the named instrument — *Cyrus... my shepherd*, foretold by name before he was born. The counsel that *shall stand* (46:10) walks the earth as a man Yahuah called from afar.'),
    ('canon','isaiah',46,11,'canon','isaiah',45,1,'free',
      E'*Thus saith Yahuah (LORD) to his anointed, to Cyrus, whose right hand I have holden, to subdue nations before him* (Isaiah 45:1). *The man that executeth my counsel from a far country: yea, I have spoken it, I will also bring it to pass* (Isaiah 46:11) is the anointed of the next breath — *Yahuah... to Cyrus, whose right hand I have holden*. The God who declares the end from the beginning names the man who fulfills it; the spoken word does not return void.')
  ) AS i(src_edition,src_slug,src_ch,src_v,tgt_edition,tgt_slug,tgt_ch,tgt_v,tier,note)
  JOIN _s303_isa46_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _s303_isa46_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- THREAD 1
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-46-bel-boweth-down-the-idols-a-dead-weight',
       E'Bel boweth down — the idols a dead weight that cannot deliver itself',
       E'The oracle opens with Babylon''s gods as cargo: *Bel boweth down, Nebo stoopeth, their idols were upon the beasts, and upon the cattle: your carriages were heavy loaden; they are a burden to the weary beast. They stoop, they bow down together; they could not deliver the burden, but themselves are gone into captivity* (Isaiah 46:1-2). The conqueror''s wagons groan under gods that cannot walk, and the gods ride off into exile with their worshippers. Jeremiah names the same impotence: *They are upright as the palm tree, but speak not: they must needs be borne, because they cannot go* (Jeremiah 10:5). The Psalm catalogues it organ by organ: *They have mouths, but they speak not... They have hands, but they handle not: feet have they, but they walk not* (Psalm 115:5,7) — and the verdict, *They that make them are like unto them; so is every one that trusteth in them* (Psalm 115:8). And the living Presence settles it in one night: when the ark stands in Dagon''s house, *Dagon was fallen upon his face to the ground before the ark of Yahuah (LORD); and the head of Dagon and both the palms of his hands were cut off upon the threshold; only the stump of Dagon was left to him* (1 Samuel 5:4). A god that must be hauled on a beast cannot deliver its burden, cannot keep its own feet, cannot save itself out of captivity. Set the idol beside Yahuah and it is a broken stump.',
       sv.verse_id, ev.verse_id, 'free', 27125
  FROM _s303_isa46_lookup sv, _s303_isa46_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=46 AND sv.verse_number=1
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=46 AND ev.verse_number=2
ON CONFLICT (slug) DO NOTHING;

-- THREAD 2 (★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-46-even-to-hoar-hairs-will-i-carry-you',
       E'Even to hoar hairs will I carry you — the idol is carried, but Yahuah carries his people',
       E'Here is the hinge of the chapter, the whole argument in one contrast: the idol must be borne, but Yahuah BEARS. *Hearken unto me, O house of Jacob, and all the remnant of the house of Yashar''el (Israel), which are borne by me from the belly, which are carried from the womb: And even to your old age I am he; and even to hoar hairs will I carry you: I have made, and I will bear; even I will carry, and will deliver you* (Isaiah 46:3-4). Where Babylon loads its gods on weary beasts, Yahuah loads his people on his own arm — from the womb to the gray head, one unbroken carrying. The Psalmist sings it from both ends of a life: *By thee have I been holden up from the womb: thou art he that took me out of my mother''s bowels* (Psalm 71:6), and *Now also when I am old and grayheaded, O Elohim (God), forsake me not* (Psalm 71:18). Moses preaches the wilderness as exactly this: *Yahuah Elohayka (the LORD thy God) bare thee, as a man doth bear his son, in all the way that ye went* (Deuteronomy 1:31). And Isaiah will remember the exodus the same way: *he bare them, and carried them all the days of old* (Isaiah 63:9) — the *angel of his presence*, the Formed One, the arm that bore Yashar''el. Then that same Formed Son says it in the flesh, to all the heavy-laden: *Come unto me, all ye that labour and are heavy laden, and I will give you rest* (Matthew 11:28). The dumb god is a burden on a beast; the living Elohim is the One who carries the burdened. And it is the WHOLE people He carries — *the house of Jacob, and all the remnant of the house of Yashar''el* (46:3), both houses borne home.',
       sv.verse_id, ev.verse_id, 'free', 27128
  FROM _s303_isa46_lookup sv, _s303_isa46_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=46 AND sv.verse_number=3
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=46 AND ev.verse_number=4
ON CONFLICT (slug) DO NOTHING;

-- THREAD 3 (★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-46-i-am-el-declaring-the-end-from-the-beginning',
       E'I am El, declaring the end from the beginning — Yahuah alone foretells and accomplishes',
       E'Against every dumb idol that cannot answer (46:7), Yahuah stakes the one claim no rival can match: *Remember the former things of old: for I am Elohim (God), and there is none else; I am Elohim (God), and there is none like me, Declaring the end from the beginning, and from ancient times the things that are not yet done, saying, My counsel shall stand, and I will do all my pleasure* (Isaiah 46:9-10). This is the Formed and the Formless against the carried god: Yahuah ALONE speaks what is not yet done and then does it — no co-equal, no rival, no idol that ever foretold. He says it across the same prophet: *calling the generations from the beginning... I am he* (Isaiah 41:4); *I have declared the former things from the beginning... I did them suddenly, and they came to pass* (Isaiah 48:3). The whole library closes on the same self-title from the throne: *I am Alpha and Omega, the beginning and the end, the first and the last* (Revelation 22:13); and the Jerusalem council confesses it of the ingathering itself, *Known unto Elohim (God) are all his works from the beginning of the world* (Acts 15:18). And the proof His counsel STANDS is a named man: *Calling a ravenous bird from the east, the man that executeth my counsel from a far country: yea, I have spoken it, I will also bring it to pass* (Isaiah 46:11) — Cyrus, foretold by name before his birth: *That saith of Cyrus, He is my shepherd, and shall perform all my pleasure* (Isaiah 44:28); *Thus saith Yahuah (LORD) to his anointed, to Cyrus, whose right hand I have holden* (Isaiah 45:1). The One who declares the end from the beginning is the One who carries his people to it; and He brings near His righteousness, placing *salvation in Zion for Yashar''el (Israel) my glory* (46:13).',
       sv.verse_id, ev.verse_id, 'free', 27131
  FROM _s303_isa46_lookup sv, _s303_isa46_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=46 AND sv.verse_number=9
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=46 AND ev.verse_number=11
ON CONFLICT (slug) DO NOTHING;

-- THREAD 1 members
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 1, E'★ *they must needs be borne, because they cannot go* (Jeremiah 10:5) — the gods *upon the beasts* of Isaiah 46:1 are Jeremiah''s carried idol; a god that must be hauled cannot walk to help.'
  FROM cross_reference_threads t
  JOIN _s303_isa46_lookup sv ON sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=46 AND sv.verse_number=1
  JOIN _s303_isa46_lookup tv ON tv.edition_slug='canon' AND tv.book_slug='jeremiah' AND tv.chapter_number=10 AND tv.verse_number=5
  JOIN cross_references cr ON cr.source_verse_id=sv.verse_id AND cr.target_verse_id=tv.verse_id AND cr.source='manual'
 WHERE t.slug='isaiah-46-bel-boweth-down-the-idols-a-dead-weight'
ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;

INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 2, E'★ *They have mouths, but they speak not: eyes have they, but they see not* (Psalm 115:5) — the dead idol of Isaiah 46:2 *gone into captivity*; every organ and no life.'
